const element = await screen.findByText('Loaded');

import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';

test('types input correctly', async () => {
  render(<input type="text" />);
  const input = screen.getByRole('textbox');

  await userEvent.type(input, 'Hello World');
  expect(input).toHaveValue('Hello World');
});

import { render } from '@testing-library/react';
import { ThemeProvider } from './ThemeContext';

const AllTheProviders = ({ children }) => {
  return <ThemeProvider>{children}</ThemeProvider>;
};

const customRender = (ui, options) =>
  render(ui, { wrapper: AllTheProviders, ...options });

export { customRender as render };

import { vi } from 'vitest';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';

test('calls onSubmit when form is submitted', async () => {
  const handleSubmit = vi.fn(); // Create spy
  render(<Form onSubmit={handleSubmit} />);

  await userEvent.click(screen.getByRole('button', { name: /submit/i }));

  expect(handleSubmit).toHaveBeenCalledTimes(1);
});

import { vi } from 'vitest';

test('triggers timer action', () => {
  vi.useFakeTimers(); // Intercept timers
  render(<TimerComponent />);

  // Fast-forward time
  vi.advanceTimersByTime(1000);

  expect(screen.getByText('Time elapsed')).toBeInTheDocument();
  vi.useRealTimers(); // Restore real timers
});

import { render, screen, waitFor } from '@testing-library/react';

test('waits for async calculation', async () => {
  render(<HeavyCalculator />);

  // Waits and retries assertions until they pass or timeout
  await waitFor(() => {
    expect(screen.getByTestId('result')).toHaveTextContent('42');
  }, { timeout: 2000 });
});

import { setupServer } from 'msw/node';
import { http, HttpResponse } from 'msw';

const server = setupServer(
  http.get('/api/data', () => {
    return HttpResponse.json({ value: 'Mock Data' });
  })
);

beforeAll(() => server.listen());
afterEach(() => server.resetHandlers());
afterAll(() => server.close());

import { render, screen } from '@testing-library/react';
import ErrorBoundary from './ErrorBoundary';

const BuggyComponent = () => {
  throw new Error('Test Error');
};

test('renders fallback on error', () => {
  // Suppress error console logging during expected throws
  const spy = vi.spyOn(console, 'error').mockImplementation(() => {});

  render(
    <ErrorBoundary fallback={<div>Crashed</div>}>
      <BuggyComponent />
    </ErrorBoundary>
  );

  expect(screen.getByText('Crashed')).toBeInTheDocument();
  spy.mockRestore();
});

